import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.CHX4lV2z.js";const g=JSON.parse('{"title":"What is LightRSI","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/what-is-lightrsi.md","filePath":"getting-started/what-is-lightrsi.md","lastUpdated":1789811186000}'),s={name:"getting-started/what-is-lightrsi.md"};function n(r,t,l,h,d,c){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="what-is-lightrsi" tabindex="-1">What is LightRSI <a class="header-anchor" href="#what-is-lightrsi" aria-label="Permalink to &quot;What is LightRSI&quot;">​</a></h1><p>LightRSI is a <strong>modular runtime for recursive improvement in long-running LLM agents</strong>. It provides the shared lifecycle, state, safety, observability, and host integration needed to build an improvement capability once and run it across OpenClaw, Codex, Claude Code, and future hosts. The current implementation focuses on context and agentic memory.</p><h2 id="lightrsi-vs-tokenpilot" tabindex="-1">Platform, Preset, and Product <a class="header-anchor" href="#lightrsi-vs-tokenpilot" aria-label="Permalink to &quot;Platform, Preset, and Product {#lightrsi-vs-tokenpilot}&quot;">​</a></h2><p>LightRSI, TokenPilot, and Context Cleaner describe different parts of the system:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;">LightRSI</td><td style="text-align:left;">Runtime and platform</td><td style="text-align:left;">Shared lifecycle, state, safety, observability, and host integration</td></tr><tr><td style="text-align:left;">TokenPilot</td><td style="text-align:left;">Context-management preset</td><td style="text-align:left;">Composes stable-prefix, reduction, and eviction capabilities</td></tr><tr><td style="text-align:left;">Context Cleaner</td><td style="text-align:left;">User-facing product</td><td style="text-align:left;">Lets users inspect tasks, approve a selection, and check the cleanup result</td></tr></tbody></table><p>Host adapters connect these capabilities to OpenClaw, Codex, Claude Code, and DeepSeek Harness. Some integrations are installed as native host plugins; supported features and product entrypoints vary by host.</p><h2 id="context-cleaner" tabindex="-1">Context Cleaner <a class="header-anchor" href="#context-cleaner" aria-label="Permalink to &quot;Context Cleaner&quot;">​</a></h2><p><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> is LightRSI&#39;s product for user-approved context cleanup. It groups session context by task, presents recommendations and protected content, and applies only an explicitly selected clean. TokenPilot supplies reusable context-management policies; Cleaner provides an interactive workflow on top of the shared task and host rewrite capabilities.</p><p>Available user entrypoints and apply timing differ by host. See the <a href="/LightRSI/user-guide/context-cleaner#supported-hosts">Cleaner host table</a> before following the workflow.</p><h2 id="what-problems-it-solves" tabindex="-1">What Problems It Solves <a class="header-anchor" href="#what-problems-it-solves" aria-label="Permalink to &quot;What Problems It Solves&quot;">​</a></h2><ul><li><strong>Long sessions get expensive</strong>. As agent sessions grow, every turn carries more context, which means more tokens and higher costs.</li><li><strong>Context is repetitive</strong>. Much of what gets sent to the model each turn is identical to the previous turn — wasteful if not cached.</li><li><strong>Tool output is noisy</strong>. Large tool responses can pollute future turns with irrelevant data.</li><li><strong>Sessions don&#39;t prune themselves</strong>. Without eviction, old context accumulates until sessions hit limits or become too slow.</li></ul><p>LightRSI provides shared infrastructure for these capabilities. TokenPilot, its first preset, composes stable-prefix rewriting, context reduction, and lifecycle-aware eviction.</p><h2 id="what-it-doesn-t-solve" tabindex="-1">What It Doesn&#39;t Solve <a class="header-anchor" href="#what-it-doesn-t-solve" aria-label="Permalink to &quot;What It Doesn&#39;t Solve&quot;">​</a></h2><ul><li><strong>Short, single-turn interactions</strong>. If your sessions are always one-shot, there is nothing for caching or eviction to optimize.</li><li><strong>Model quality or accuracy</strong>. LightRSI doesn&#39;t change model behavior — it changes what context gets sent to the model.</li><li><strong>All memory problems</strong>. Long-term memory is an experimental feature area; TokenPilot focuses on the current session&#39;s context window.</li></ul><h2 id="relationship-to-the-paper" tabindex="-1">Relationship to the Paper <a class="header-anchor" href="#relationship-to-the-paper" aria-label="Permalink to &quot;Relationship to the Paper&quot;">​</a></h2><p>The <a href="https://arxiv.org/abs/2606.17016" target="_blank" rel="noreferrer">TokenPilot paper</a> describes the cache-efficient context management technique. TokenPilot is LightRSI&#39;s first preset.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/LightRSI/getting-started/quick-start">Quick Start</a> — get running in under 5 minutes</li><li><a href="/LightRSI/platform-concepts/core-runtime">Core Concepts</a> — understand the platform architecture</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot Overview</a> — explore the context-management preset</li><li><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> — review and approve task-level cleanup</li></ul>',18)])])}const u=e(s,[["render",n]]);export{g as __pageData,u as default};
